<?php $m = $args['model'] ?? array(); $p = $m['profile'] ?? array(); $google = $m['google_state'] ?? 'unknown'; $google_states = array( 'not_connected', 'connected', 'needs_attention', 'unavailable' ); $google_valid = in_array( $google, $google_states, true ); $payment = $m['payment_state'] ?? 'unknown'; $payment_states = array( 'pending_verification', 'confirmed', 'paid', 'unavailable' ); $availability_available = false !== ( $m['availability_available'] ?? true ); ?>
<section class="dzn-tp-section" aria-labelledby="tp-profile"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">مشخصات</p><h2 id="tp-profile">اطلاعات شخصی</h2></div></div><div class="dzn-tp-form-grid"><label>نام<input value="<?php echo esc_attr( $p['name'] ?? '' ); ?>"></label><label>ایمیل<input type="email" dir="ltr" value="<?php echo esc_attr( $p['email'] ?? '' ); ?>"></label><label>WhatsApp / همراه الزامی<input type="tel" dir="ltr" required value="<?php echo esc_attr( $p['mobile'] ?? '' ); ?>"<?php if ( '' === trim( (string) ( $p['mobile'] ?? '' ) ) ) : ?> placeholder="ثبت نشده"<?php endif; ?>><?php if ( '' === trim( (string) ( $p['mobile'] ?? '' ) ) ) : ?><span class="dzn-tp-help">شمارهٔ WhatsApp از منبع معتبر دریافت نشده است؛ پس از اتصال امن قابل ویرایش می‌شود.</span><?php endif; ?></label><label>منطقهٔ زمانی<select><option><?php echo esc_html( $p['timezone_label'] ?? 'انتخاب نشده' ); ?></option></select></label><label>نوع تقویم<select><option value="gregorian"<?php selected( $p['calendar'] ?? '', 'gregorian' ); ?>>میلادی</option><option value="persian"<?php selected( $p['calendar'] ?? '', 'persian' ); ?>>خورشیدی / هجری شمسی</option></select></label></div><button class="dzn-button" type="button" data-dzn-tp-presentation>ذخیره در آینده</button><p class="dzn-tp-action-status" aria-live="polite"></p></section>
<section class="dzn-tp-section" aria-labelledby="tp-google"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">کلاس آنلاین</p><h2 id="tp-google">اتصال Google</h2></div><span class="dzn-tp-state is-<?php echo esc_attr( $google_valid ? $google : 'unknown' ); ?>"><?php echo esc_html( $google_valid ? array( 'not_connected' => 'متصل نیست', 'connected' => 'متصل', 'needs_attention' => 'نیازمند توجه', 'unavailable' => 'وضعیت در دسترس نیست' )[ $google ] : 'وضعیت در دسترس نیست' ); ?></span></div><?php if ( 'connected' === $google ) : ?><p>حساب Google شما برای تقویم کلاس و Google Meet متصل است.</p><form method="post" action="<?php echo esc_url( (string) ( $m['google_disconnect_url'] ?? '' ) ); ?>"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr( (string) ( $m['google_disconnect_nonce'] ?? '' ) ); ?>"><button class="dzn-button" type="submit">قطع اتصال Google</button></form><?php elseif ( 'unavailable' === $google ) : ?><p>اتصال Google هنوز توسط دلنوازان پیکربندی نشده است.</p><?php else : ?><p>برای ساخت تقویم کلاس و پیوند امن Google Meet، حساب Google خود را متصل کنید.</p><form method="post" action="<?php echo esc_url( (string) ( $m['google_action_url'] ?? '' ) ); ?>"><input type="hidden" name="_wpnonce" value="<?php echo esc_attr( (string) ( $m['google_nonce'] ?? '' ) ); ?>"><button class="dzn-button" type="submit"><?php echo esc_html( 'needs_attention' === $google ? 'اتصال دوباره' : 'اتصال Google' ); ?></button></form><?php endif; ?><?php $google_status = sanitize_key( (string) ( $_GET['google_status'] ?? '' ) ); if ( 'google_connected' === $google_status ) : ?><p class="dzn-tp-action-status" aria-live="polite">اتصال Google با موفقیت انجام شد.</p><?php elseif ( 'google_disconnected' === $google_status ) : ?><p class="dzn-tp-action-status" aria-live="polite">اتصال Google قطع شد.</p><?php elseif ( in_array( $google_status, array( 'google_connect_failed', 'google_not_configured', 'google_disconnect_failed' ), true ) ) : ?><p class="dzn-tp-action-status" aria-live="polite">اتصال Google انجام نشد. لطفاً دوباره تلاش کنید یا با پشتیبانی تماس بگیرید.</p><?php endif; ?></section>
<section class="dzn-tp-section" aria-labelledby="tp-availability"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker"><?php echo esc_html( $p['timezone_label'] ?? 'زمان مدرس' ); ?></p><h2 id="tp-availability">زمان‌های در دسترس</h2></div><span>پیشنهاد، نه محدودیت</span></div><?php if ( $availability_available ) : ?><p class="dzn-tp-recommended">ساعت‌های پیشنهادی دلنوازان: ۱۶:۰۰ تا ۲۱:۰۰</p><div class="dzn-tp-availability"><?php foreach ( $m['availability'] ?? array() as $day ) : ?><article><h3><?php echo esc_html( $day['day'] ?? '' ); ?></h3><?php foreach ( $day['blocks'] ?? array() as $block ) : ?><span class="is-available"><?php echo esc_html( $block ); ?></span><?php endforeach; ?><?php if ( ! empty( $day['booked'] ) ) : ?><span class="is-booked">کلاس رزروشده: <?php echo esc_html( $day['booked'] ); ?></span><?php endif; ?><button type="button" data-dzn-tp-presentation>افزودن بازه</button></article><?php endforeach; ?></div><?php if ( $m['exceptions'] ?? array() ) : ?><h3>استثناهای تاریخ‌دار</h3><ul><?php foreach ( $m['exceptions'] as $exception ) : ?><li><?php echo esc_html( $exception ); ?></li><?php endforeach; ?></ul><?php endif; ?><button class="dzn-button" type="button" data-dzn-tp-presentation>ویرایش در آینده</button><?php else : ?><p class="dzn-tp-help">زمان‌های در دسترس هنوز در نمای خواندنی پرتال ارائه نشده‌اند.</p><?php endif; ?><p class="dzn-tp-action-status" aria-live="polite"></p></section>
<section class="dzn-tp-section" aria-labelledby="tp-payments"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">نمایش مالی</p><h2 id="tp-payments">پرداخت‌ها و صورت‌حساب‌ها</h2></div><span class="dzn-tp-state"><?php echo esc_html( in_array( $payment, $payment_states, true ) ? array( 'pending_verification' => 'در انتظار بررسی', 'confirmed' => 'تأییدشده برای پرداخت', 'paid' => 'پرداخت‌شده', 'unavailable' => 'در دسترس نیست' )[ $payment ] : 'وضعیت در دسترس نیست' ); ?></span></div><?php if ( in_array( $payment, array( 'pending_verification', 'confirmed', 'paid' ), true ) ) : ?><div class="dzn-tp-stats"><div><strong>۲۶</strong><span>کلاس این ماه</span></div><div><strong>۱۹٫۵</strong><span>ساعت تدریس</span></div><div><strong>—</strong><span>مبلغ از مرجع معتبر</span></div></div><article class="dzn-tp-statement"><strong>صورت‌حساب شهریور</strong><span>در انتظار بررسی مرجع مالی</span><button type="button" disabled>دریافت در آینده</button></article><?php endif; ?><p class="dzn-tp-help">پوسته قابلیت محاسبه یا تأیید پرداخت را ندارد.</p></section>
<section class="dzn-tp-section" aria-labelledby="tp-stats"><div class="dzn-tp-heading"><div><p class="dzn-tp-kicker">نمای کلی</p><h2 id="tp-stats">آمار تدریس</h2></div></div><div class="dzn-tp-stats"><?php foreach ( array( 'active_students' => 'هنرجوی فعال', 'lessons_month' => 'کلاس این ماه', 'hours_month' => 'ساعت تدریس', 'upcoming' => 'کلاس پیش رو', 'year_total' => 'کلاس امسال' ) as $key => $label ) : ?><div><strong><?php echo esc_html( $m['statistics'][ $key ] ?? '—' ); ?></strong><span><?php echo esc_html( $label ); ?></span></div><?php endforeach; ?></div></section>
<section class="dzn-tp-section"><h2>امنیت و مدیریت حساب</h2><p>رمز عبور و دسترسی حساب در یکپارچه‌سازی امن آینده مدیریت می‌شود.</p><button type="button" disabled>تغییر رمز در آینده</button></section><?php dzn_theme_teacher_portal_component( 'help' ); ?>
